@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @bind="searchText"
           @bind:event="oninput"
           @bind:after="OnSearchTextChanged" />

    @if (isLoading)
    {
        <div class="product-search__status">Searching…</div>
    }
    else if (errorMessage is not null)
    {
        <div class="product-search__error">
            <span>@errorMessage</span>
            <button @onclick="RetrySearch">Retry</button>
        </div>
    }
    else if (hasSearched && products.Count == 0)
    {
        <div class="product-search__status">No products found.</div>
    }

    @if (products.Count > 0)
    {
        <div class="product-search__results">
            @foreach (var product in products)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img class="product-card__image" src="@product.ImageUrl" alt="@product.Name" />
                    <div class="product-card__info">
                        <span class="product-card__name">@product.Name</span>
                        <span class="product-card__price">@product.Price.ToString("C")</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string searchText = string.Empty;
    private List<Product> products = new();
    private bool isLoading;
    private bool hasSearched;
    private string? errorMessage;

    private Timer? debounceTimer;
    private CancellationTokenSource? searchCts;

    private async Task OnSearchTextChanged()
    {
        errorMessage = null;
        debounceTimer?.Dispose();

        var query = searchText.Trim();
        if (string.IsNullOrEmpty(query))
        {
            CancelInflightSearch();
            products = new();
            hasSearched = false;
            return;
        }

        // Capture a local copy so the timer callback closes over the correct value.
        var captured = query;
        debounceTimer = new Timer(_ => InvokeAsync(() => ExecuteSearch(captured)), null, 300, Timeout.Infinite);
    }

    private async Task ExecuteSearch(string query)
    {
        CancelInflightSearch();

        var cts = new CancellationTokenSource();
        searchCts = cts;

        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            var results = await ProductService.SearchAsync(query, cts.Token);

            // Only apply results if this search was not superseded.
            if (!cts.Token.IsCancellationRequested)
            {
                products = results;
                hasSearched = true;
            }
        }
        catch (OperationCanceledException)
        {
            // Search was intentionally abandoned; nothing to do.
        }
        catch (Exception)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                products = new();
                errorMessage = "Something went wrong. Please try again.";
            }
        }
        finally
        {
            if (searchCts == cts)
            {
                isLoading = false;
                StateHasChanged();
            }

            cts.Dispose();
        }
    }

    private async Task RetrySearch()
    {
        var query = searchText.Trim();
        if (!string.IsNullOrEmpty(query))
        {
            await ExecuteSearch(query);
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private void CancelInflightSearch()
    {
        searchCts?.Cancel();
        searchCts?.Dispose();
        searchCts = null;
    }

    public void Dispose()
    {
        debounceTimer?.Dispose();
        CancelInflightSearch();
    }
}

